-- Complete Back Squat with explicit high-bar and low-bar working specifications.
-- Every legacy source remains traceable but nonselectable because exact setup,
-- depth, tempo/pause, rack, safety, and completion facts are absent. Evidence,
-- media, graph, calibration, and publication remain human-review quarantined.

DO $$
DECLARE
  migration_key CONSTANT TEXT := '461_coaching_back_squat_family_completion';
  research_version CONSTANT TEXT := '2026-08-02.73';
  canonical_id CONSTANT UUID := '1ad09283-aa35-486f-b6bf-bdbdc1b575ee';
  high_bar_variant CONSTANT UUID := 'a8a9db64-1c8a-4879-9b6b-8d91940b82c0';
  low_bar_variant CONSTANT UUID := '76351482-a34d-43cc-bcb3-0d4d6f1decde';
  front_squat_variant CONSTANT UUID := '7f01a800-dcde-4a2a-adcd-7cd320283040';
  box_squat_variant CONSTANT UUID := 'ddf3b4f0-41a0-4b40-8c86-6b688d0531a9';
  pin_squat_variant CONSTANT UUID := 'ee40010f-2ff2-4233-9140-a7d3ef3ff5ce';
  tempo_five_variant CONSTANT UUID := 'fb27d5fa-e9b6-48e5-bdbd-03fe23a87881';
  source_ids CONSTANT BIGINT[] := ARRAY[1,367,368,370,371];
  source_variant_ids CONSTANT UUID[] := ARRAY[
    'd5f83616-4866-4fd7-b294-ed5bae9319ec'::UUID,
    '8190a71e-0f15-47c0-b6a5-cf9158b1782c'::UUID,
    '420259b4-bffa-478b-9574-a9059d4759aa'::UUID,
    '8d49d08a-4a03-4100-a0ef-06932ffadd1b'::UUID,
    '13517498-3902-41e9-8b8b-8fd33759dbd0'::UUID];
  active_variant_ids CONSTANT UUID[] := ARRAY[high_bar_variant,low_bar_variant];
  archived_definition_ids CONSTANT UUID[] := ARRAY[
    '57bc5cdb-b4a7-4840-ada0-920b335898b7'::UUID,
    '80d7a8c7-58a9-462c-92c5-bb01dc98222c'::UUID,
    '5e699119-b268-451c-9153-299f8830f151'::UUID,
    '19435984-9e81-49a8-8939-fa3659df01f1'::UUID];
  current_video_ids CONSTANT TEXT[] := ARRAY[
    '8Kls95w2jFA','Akd5xmZlsvg','Po9CDtfcLJI','1le_LVZmmUU','7fmrKmJMQnw'];
  evidence_payload JSONB := $json$
  [
    {"sectionKey":"identity","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/38900172/","sourceTitle":"A Biomechanical Comparison Between a High and Low Barbell Placement on Net Joint Moments, Kinematics, Muscle Forces, and Muscle-Specific Moments in 3 Repetition Maximum Back Squats","sourcePublisher":"Journal of Strength and Conditioning Research","sourceKind":"peer_reviewed_research","evidenceQuality":90,"claims":["The study directly compared high- and low-bar placements under standardized stance in 12 recreationally trained men.","Back Squat is a bilateral free-bar squat with the bar supported on the posterior shoulder-girdle region; bar position is an exact variant fact, while front, safety-bar, box, pin, jump, and split squats remain distinct tasks."]},
    {"sectionKey":"taxonomy","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Professional instruction distinguishes bar-on-back squat setup and power-rack safety from other squat loading interfaces.","Controlled taxonomy is squat plus brace; bar position, stance, depth, tempo, and load are variant or delivery dimensions, not athlete proficiency levels."]},
    {"sectionKey":"anatomy","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/30335723/","sourceTitle":"Hip and Knee Kinetics During a Back Squat and Deadlift","sourcePublisher":"Journal of Strength and Conditioning Research","sourceKind":"peer_reviewed_research","evidenceQuality":88,"claims":["In 28 resistance-trained adults, back squat produced substantial hip and knee extensor moments and more knee extensor moment and work than deadlift under the studied loads.","The card includes hip, knee, ankle, foot, pelvis, spine, shoulder-girdle support, and trunk-bracing demands without claiming one universal muscle contribution ranking."]},
    {"sectionKey":"biomechanics","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/34541522/","sourceTitle":"Effects of Stance Width and Barbell Placement on Kinematics, Kinetics, and Myoelectric Activity in Back Squats","sourcePublisher":"Frontiers in Sports and Active Living","sourceKind":"peer_reviewed_research","evidenceQuality":88,"claims":["Eighteen adults performed four high/low-bar and narrow/wide-stance 3RM conditions; combined bar position and stance affected joint contribution and activity around the sticking region.","Bar position cannot be interpreted independently of stance, depth, load, anthropometry, and technique, so the card records all of those variables."]},
    {"sectionKey":"difficulty","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/38900172/","sourceTitle":"A Biomechanical Comparison Between a High and Low Barbell Placement on Net Joint Moments, Kinematics, Muscle Forces, and Muscle-Specific Moments in 3 Repetition Maximum Back Squats","sourcePublisher":"Journal of Strength and Conditioning Research","sourceKind":"peer_reviewed_research","evidenceQuality":90,"claims":["The high- and low-bar 3RM loads did not significantly differ in the small standardized-stance cohort, and no significant lower-extremity moment or estimated muscle-force difference was found.","Difficulty is provisional exercise complexity plus physical difficulty, with overall derived as their maximum; athlete readiness is assessed separately during workout selection."]},
    {"sectionKey":"load_fatigue_recovery","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/38036316/","sourceTitle":"Support moment distribution during the back squat at different depths and loads in recreationally trained females","sourcePublisher":"Journal of Science and Medicine in Sport","sourceKind":"peer_reviewed_research","evidenceQuality":88,"claims":["Nineteen women performed three depths and three depth-specific load conditions; load and depth changed lower-extremity joint moments and their distribution.","Track bar mass, depth, stance, repetitions, tempo, effort reserve, technical loss, recent lower-body and axial loading, symptoms, and individualized recovery rather than treating one label as one exposure."]},
    {"sectionKey":"constraints","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Back-loaded barbell exercise requires a suitable rack and safety or spotting plan.","Selection verifies rack, hooks, safeties, bar, plates, collars under facility policy, clear walkout, footing, ceiling, observers, rerack, and emergency response before loading."]},
    {"sectionKey":"dosage","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/","sourceTitle":"American College of Sports Medicine Position Stand. Resistance Training Prescription for Muscle Function, Hypertrophy, and Physical Performance in Healthy Adults: An Overview of Reviews","sourcePublisher":"Medicine and Science in Sports and Exercise","sourceKind":"professional_standard","evidenceQuality":96,"claims":["Resistance prescription depends on objective, load, volume, effort, frequency, and individual response.","Profiles declare repetitions, sets, depth, tempo, reserve, rest, duration, scaling, and cumulative lower-body and axial exposure; no universal dose is asserted."]},
    {"sectionKey":"instructions","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Professional instruction makes rack setup, bar position, stance, controlled descent/ascent, and safety assistance observable.","Instructions identify exact variant, grip and bar shelf, rack and safety height, walkout, stance, depth target, tempo, breathing/brace plan, repetition validity, rerack, and stop criteria."]},
    {"sectionKey":"safety_stop_rules","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4064719/","sourceTitle":"Knee joint kinetics in relation to commonly prescribed squat loads and depths","sourcePublisher":"Journal of Strength and Conditioning Research","sourceKind":"peer_reviewed_research","evidenceQuality":88,"claims":["In 16 trained men, peak external knee flexion moment increased with both depth and load across the tested conditions.","Stop for pain, neurologic or cardiopulmonary symptoms, unsafe rack or safety setup, bar movement on the back, foot loss, uncontrolled depth, brace or path failure, unexpected contact, missed-rep risk, or rerack uncertainty; the card does not provide clinical clearance."]},
    {"sectionKey":"programming","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/31230110/","sourceTitle":"Effects of squat training with different depths on lower limb muscle volumes","sourcePublisher":"European Journal of Applied Physiology","sourceKind":"peer_reviewed_research","evidenceQuality":88,"claims":["Seventeen men completed 10 weeks of full- or half-squat training; strength gains were depth-specific and muscle-volume responses differed by muscle and group.","Depth is recorded and prescribed rather than assumed, and substitutions recompute exact variant, load, range, fatigue, recovery, duration, logistics, and rendering."]},
    {"sectionKey":"athlete_support","sourceUrl":"https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf","sourceTitle":"Basics of Strength and Conditioning Manual","sourcePublisher":"National Strength and Conditioning Association","sourceKind":"professional_standard","evidenceQuality":84,"claims":["Rack, bar placement, stance, movement, and spotting expectations can be communicated as visible checkpoints.","Athlete support names expected effort, self-checks, stop signals, rerack commands, and nonvideo instructions without equating difficulty with skill level."]},
    {"sectionKey":"coach_support","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/37001335/","sourceTitle":"The effect of trunk and shank position on the hip-to-knee moment ratio in a bilateral squat","sourcePublisher":"Physical Therapy in Sport","sourceKind":"peer_reviewed_research","evidenceQuality":87,"claims":["Across 100 participants and multiple squat depths, trunk and shank angles were associated with hip-to-knee moment distribution.","Coach support observes bar shelf and path, trunk and shank strategy, foot pressure, hip/knee/ankle motion, depth, tempo, brace, fatigue, walkout, and rerack while avoiding one universal torso-angle rule."]},
    {"sectionKey":"accessibility","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/","sourceTitle":"American College of Sports Medicine Position Stand. Resistance Training Prescription for Muscle Function, Hypertrophy, and Physical Performance in Healthy Adults: An Overview of Reviews","sourcePublisher":"Medicine and Science in Sports and Exercise","sourceKind":"professional_standard","evidenceQuality":96,"claims":["Resistance training can be individualized through load, volume, range, equipment, supervision, and exercise choice.","Accessible delivery may reduce load, repetitions, or range, increase rest and setup time, add visual marks and nonvideo instruction, or select a separately reviewed squat interface; it does not silently change bar position or safety requirements."]},
    {"sectionKey":"alternates","sourceUrl":"https://pubmed.ncbi.nlm.nih.gov/38900172/","sourceTitle":"A Biomechanical Comparison Between a High and Low Barbell Placement on Net Joint Moments, Kinematics, Muscle Forces, and Muscle-Specific Moments in 3 Repetition Maximum Back Squats","sourcePublisher":"Journal of Strength and Conditioning Research","sourceKind":"peer_reviewed_research","evidenceQuality":90,"claims":["High- and low-bar placements are directly comparable variants, but findings from a small standardized-stance male cohort do not establish universal superiority.","Bar interface, stance, heel elevation, depth, pause, tempo, accommodating resistance, machine guidance, box/pin contact, and compound or ballistic actions determine modifier, variant, or new-definition classification."]},
    {"sectionKey":"media","sourceUrl":"https://support.google.com/youtube/answer/171780?expand=PrivacyEnhancedMode&hl=en","sourceTitle":"Embed videos and playlists","sourcePublisher":"YouTube Help","sourceKind":"manufacturer_instruction","evidenceQuality":82,"claims":["YouTube supports privacy-enhanced embedding through youtube-nocookie.com.","Five candidates have current oEmbed link, title, channel, and iframe metadata only; playback, exact variant, captions, accessibility, safety, quality, reviewer identity, and approval remain unresolved."]}
  ] $json$::JSONB;
  media_payload JSONB := $json$
  [
    {"videoId":"8Kls95w2jFA","title":"Perfect Your Squat: Step-By-Step Form Guide","channel":"Squat University","variant":"general","query":"back squat form guide"},
    {"videoId":"Akd5xmZlsvg","title":"Back Squat | Olympic Weightlifting Exercise Library","channel":"Catalyst Athletics","variant":"high","query":"high bar back squat exercise"},
    {"videoId":"Po9CDtfcLJI","title":"How to Perform a Low Bar Back Squat","channel":"Squat University","variant":"low","query":"low bar back squat"},
    {"videoId":"1le_LVZmmUU","title":"How to Coach the High Bar Back Squat | CrossFit Movement Breakdown with Nicole Christensen","channel":"CrossFit","variant":"high","query":"high bar back squat coaching"},
    {"videoId":"7fmrKmJMQnw","title":"How To Low Bar Squat","channel":"CanditoTrainingHQ","variant":"low","query":"low bar squat coaching"}
  ] $json$::JSONB;
  alternate_payload JSONB := $json$
  [
    {"name":"High-Bar Back Squat","class":"new_variant","why":"Bar shelf on the upper trapezius is an exact posterior-load variant with its own grip, torso, stance, depth, and safety contract.","dimensions":{"variantKey":"high-bar-free-bar-parallel","barPosition":"upper_trapezius"}},
    {"name":"Low-Bar Back Squat","class":"new_variant","why":"Bar shelf across the posterior deltoid region changes shoulder position, torso strategy, bar path, and setup while preserving the free-bar bilateral squat identity.","dimensions":{"variantKey":"low-bar-free-bar-parallel","barPosition":"posterior_deltoid_shelf"}},
    {"name":"Generic Back Squat Source","class":"reject","why":"Source 1 contains jump and landing contamination and omits exact bar position, stance, grip, depth, walkout, tempo, and safety setup.","dimensions":{"sourceIds":[1],"identityQuarantine":true}},
    {"name":"Legacy High-Bar Source","class":"reject","why":"Source 367 names the bar position but leaves exact stance, grip, depth, walkout, tempo, rack safeties, and rerack contract unresolved.","dimensions":{"sourceIds":[367],"identityQuarantine":true}},
    {"name":"Legacy Low-Bar Source","class":"reject","why":"Source 368 names the bar position but leaves exact stance, grip, depth, walkout, tempo, rack safeties, and rerack contract unresolved.","dimensions":{"sourceIds":[368],"identityQuarantine":true}},
    {"name":"Pause Back Squat","class":"new_variant","why":"A pause requires exact bar position, stance, depth, duration, rebound policy, load, breathing, and completion criteria; source 370 does not supply them.","dimensions":{"sourceIds":[370],"pauseDuration":"must_be_declared"}},
    {"name":"Tempo Back Squat","class":"new_variant","why":"Tempo changes time under tension and fatigue but requires exact bar position and phase durations; source 371 supplies neither.","dimensions":{"sourceIds":[371],"tempo":"must_be_declared"}},
    {"name":"Five-Second-Lower Back Squat","class":"new_variant","why":"The existing exact five-second-lower card changes eccentric duration and recovery while preserving the squat cycle.","dimensions":{"existingDefinition":"tempo-back-squat-5-second-lower"}},
    {"name":"Above-Parallel Back Squat","class":"new_variant","why":"A declared partial depth changes load capacity, joint moments, range, measurement, and transfer.","dimensions":{"depth":"above_parallel_declared"}},
    {"name":"Below-Parallel or Full Back Squat","class":"new_variant","why":"A deeper declared bottom changes range, mobility demand, depth-specific load, joint moments, and valid-repetition criteria.","dimensions":{"depth":"below_parallel_or_full_declared"}},
    {"name":"Narrow-Stance Back Squat","class":"new_variant","why":"Stance width interacts with bar position and changes joint motion and loading.","dimensions":{"stanceWidth":"declared_narrow"}},
    {"name":"Wide-Stance Back Squat","class":"new_variant","why":"Stance width and foot angle require an exact contract and cannot be inferred from low-bar naming.","dimensions":{"stanceWidth":"declared_wide"}},
    {"name":"Heels-Elevated Back Squat","class":"new_variant","why":"A wedge or plates change foot interface, ankle/knee range, balance, load distribution, and failure setup.","dimensions":{"heelElevation":"declared","equipment":"wedge_or_plates"}},
    {"name":"Box Squat","class":"new_definition","why":"Intentional box contact adds target height, touch-or-sit behavior, pressure transfer, reversal, and box safety.","dimensions":{"existingDefinition":"box-squat"}},
    {"name":"Pin Squat","class":"new_definition","why":"Starting or stopping on safeties changes contraction sequence, pin height, bar contact, and escape plan.","dimensions":{"existingDefinition":"pin-squat"}},
    {"name":"Anderson Squat","class":"new_definition","why":"A dead start from pins changes start position and eliminates the standard walkout-and-descent sequence.","dimensions":{"existingDefinition":"anderson-squat"}},
    {"name":"Barbell Front Squat","class":"new_definition","why":"Anterior shoulder-girdle loading changes support interface, grip, torso strategy, failure response, and rerack.","dimensions":{"existingDefinition":"front-squat"}},
    {"name":"Safety-Squat-Bar Squat","class":"new_variant","why":"A safety bar changes bar geometry, handles, torso position, load capacity, and failure interaction.","dimensions":{"barType":"safety_squat_bar"}},
    {"name":"Cambered or Buffalo-Bar Back Squat","class":"new_variant","why":"Specialty-bar geometry changes grip, oscillation, load position, clearance, and rack handling.","dimensions":{"barType":"specialty_bar_declared"}},
    {"name":"Band- or Chain-Resisted Back Squat","class":"new_variant","why":"Accommodating resistance changes load through range, anchoring or chain setup, stability, and hazard controls.","dimensions":{"resistanceCurve":"declared_accommodating"}},
    {"name":"Smith-Machine Back Squat","class":"new_definition","why":"A guided bar path and machine hooks/stops materially change balance, trajectory, setup, and exit.","dimensions":{"barPath":"machine_guided"}},
    {"name":"Back Squat to Calf Raise","class":"new_definition","why":"Adding terminal plantarflexion creates a compound action and different repetition and balance criteria.","dimensions":{"compoundAction":"squat_plus_calf_raise"}},
    {"name":"Loaded Back Squat Jump","class":"new_definition","why":"Takeoff, flight, landing, impact contacts, ballistic intent, and landing quality create a separate exercise.","dimensions":{"flight":true,"landingContacts":"tracked"}},
    {"name":"Spotter-Assisted Failed Back Squat","class":"reject","why":"A missed repetition is an incident or test outcome, not a selectable exercise variant.","dimensions":{"selectable":false,"incident":true}}
  ] $json$::JSONB;
BEGIN
  IF (SELECT count(*) FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND facility_id=1 AND slug='back-squat')<>1
    OR (SELECT count(*) FROM coaching.exercise WHERE id=ANY(source_ids))<>5
    OR (SELECT count(*) FROM coaching.exercise_definition_source_v1 WHERE legacy_exercise_id=ANY(source_ids))<>5
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id=ANY(source_variant_ids))<>5
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id IN (front_squat_variant,box_squat_variant,pin_squat_variant,tempo_five_variant) AND status<>'archived')<>4
    OR EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND (reviewed_by IS NOT NULL OR approved_by IS NOT NULL OR last_reviewed_at IS NOT NULL))
    OR EXISTS(SELECT 1 FROM coaching.exercise_identity_resolution_v1 WHERE reviewed_by IS NOT NULL AND (survivor_definition_id=canonical_id OR resolved_definition_id=ANY(archived_definition_ids))) THEN
    RAISE EXCEPTION '% refuses missing lineage, related variants, or human-reviewed state',migration_key;
  END IF;

  UPDATE coaching.exercise_section_evidence_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;
  UPDATE coaching.exercise_media_candidate_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;
  UPDATE coaching.exercise_alternate_assessment_v1 SET review_status='superseded',updated_at=now()
  WHERE definition_id=canonical_id AND review_status='candidate' AND reviewer_user_id IS NULL;

  UPDATE coaching.exercise_definition_source_v1 SET definition_id=canonical_id,
    source_kind=CASE WHEN legacy_exercise_id=1 THEN 'legacy_migration' ELSE 'duplicate_consolidation' END,
    provenance_json=coalesce(provenance_json,'{}'::JSONB)||jsonb_build_object(
      'migration',migration_key,'sourceDisposition','identity_quarantine','representedBySelectableSourceVariant',FALSE,
      'representedByResearchWorkingSpecification',legacy_exercise_id IN (367,368),
      'missingExactExecutionFacts',TRUE,'humanReviewRequired',TRUE,'approvalsCreated',FALSE)
  WHERE legacy_exercise_id=ANY(source_ids);

  UPDATE coaching.exercise_variant_v1 SET definition_id=canonical_id,
    variant_key='identity-quarantine-source-'||(CASE id
      WHEN 'd5f83616-4866-4fd7-b294-ed5bae9319ec'::UUID THEN 1
      WHEN '8190a71e-0f15-47c0-b6a5-cf9158b1782c'::UUID THEN 367
      WHEN '420259b4-bffa-478b-9574-a9059d4759aa'::UUID THEN 368
      WHEN '8d49d08a-4a03-4100-a0ef-06932ffadd1b'::UUID THEN 370 ELSE 371 END)::TEXT,
    status='archived',difficulty_json='{}'::JSONB,
    requirements_json=jsonb_build_object('selectable',FALSE,'representation','identity_quarantine',
      'sourceLegacyExerciseId',CASE id
        WHEN 'd5f83616-4866-4fd7-b294-ed5bae9319ec'::UUID THEN 1
        WHEN '8190a71e-0f15-47c0-b6a5-cf9158b1782c'::UUID THEN 367
        WHEN '420259b4-bffa-478b-9574-a9059d4759aa'::UUID THEN 368
        WHEN '8d49d08a-4a03-4100-a0ef-06932ffadd1b'::UUID THEN 370 ELSE 371 END,
      'archiveReason',CASE id
        WHEN 'd5f83616-4866-4fd7-b294-ed5bae9319ec'::UUID THEN 'generic_source_contains_jump_landing_contamination_and_omits_exact_bar_position_stance_depth_walkout_tempo_and_safety_setup'
        WHEN '8190a71e-0f15-47c0-b6a5-cf9158b1782c'::UUID THEN 'high_bar_label_omits_exact_grip_stance_depth_walkout_tempo_safeties_and_rerack'
        WHEN '420259b4-bffa-478b-9574-a9059d4759aa'::UUID THEN 'low_bar_label_omits_exact_grip_stance_depth_walkout_tempo_safeties_and_rerack'
        WHEN '8d49d08a-4a03-4100-a0ef-06932ffadd1b'::UUID THEN 'pause_source_omits_bar_position_pause_depth_duration_rebound_policy_and_safety_contract'
        ELSE 'tempo_source_omits_bar_position_and_all_phase_durations_plus_exact_safety_contract' END,
      'originalAuthoritativeEvidenceRequired',TRUE,'humanReviewRequired',TRUE),
    load_profile_json=jsonb_build_object('selectable',FALSE),fatigue_profile_json=jsonb_build_object('selectable',FALSE),
    programming_profile_json=jsonb_build_object('selectionStatus','identity_quarantine','selectable',FALSE,'publicationQuarantined',TRUE,'neverRestoreFromLabelOrMediaMetadata',TRUE),updated_at=now()
  WHERE id=ANY(source_variant_ids);
  UPDATE coaching.exercise_delivery_profile_v1 SET status='archived',updated_at=now() WHERE variant_id=ANY(source_variant_ids);

  UPDATE coaching.exercise_definition_v1 SET status='archived',approved_video_url=NULL,reviewed_by=NULL,approved_by=NULL,last_reviewed_at=NULL,
    provenance_json=coalesce(provenance_json,'{}'::JSONB)||jsonb_build_object('identityResolutionMigration',migration_key,'survivorDefinitionId',canonical_id,'selectable',FALSE,'humanReviewRequired',TRUE,'approvalsCreated',FALSE),updated_at=now()
  WHERE id=ANY(archived_definition_ids);

  UPDATE coaching.exercise_definition_v1 SET canonical_name='Back Squat',display_name='Back Squat',
    aliases=ARRAY['Barbell Back Squat','High-Bar Back Squat','Low-Bar Back Squat']::TEXT[],
    description='A bilateral free-bar squat with the bar supported on an explicitly declared posterior shoulder-girdle shelf. Every working specification declares bar position, grip, rack and safety height, walkout, stance and foot angle, depth, tempo, breathing and brace plan, repetitions, load, reserve, rest, rerack, and stop rules.',
    family_key='bilateral_free_bar_back_squat_family',schema_version='2.0.0',card_version=2,status='review',
    content_confidence=91,scoring_confidence=66,media_confidence=48,
    movement_patterns=ARRAY['squat','brace']::TEXT[],body_regions=ARRAY['hip','knee','ankle']::TEXT[],
    required_equipment=ARRAY['barbell','plates','squat_rack','timer']::TEXT[],optional_equipment=ARRAY[]::TEXT[],
    anatomy_json=jsonb_build_object(
      'primaryMuscles',jsonb_build_array('quadriceps','gluteus_maximus','adductor_magnus'),
      'secondaryMuscles',jsonb_build_array('hamstrings','spinal_erectors','abdominal_wall','obliques','calf_complex','foot_intrinsics','upper_back_and_shoulders_for_bar_support'),
      'connectiveTissues',jsonb_build_array('patellar_tendon','quadriceps_tendon','hip_capsule_and_supporting_tissues','spinal_and_pelvic_supporting_tissues','foot_and_ankle_supporting_tissues'),
      'joints',jsonb_build_array('hip','knee','talocrural_ankle','subtalar_and_midfoot','pelvis','lumbar_and_thoracic_spine','shoulder_girdle_and_elbow_for_bar_support'),
      'jointActions',jsonb_build_array('hip_and_knee_flexion_during_descent','controlled_ankle_dorsiflexion_during_descent','hip_and_knee_extension_during_ascent','ankle_plantarflexor_contribution','isometric_trunk_and_pelvic_bracing','upper_back_and_arm_isometric_bar_support'),
      'planes',jsonb_build_array('sagittal_primary','frontal_and_transverse_control'),
      'laterality','bilateral_with_side_specific_observation','lateralityDetail','Both feet contribute; record asymmetric pressure, path, depth, symptoms, and recovery rather than assuming symmetry.',
      'evidenceLimit','Small biomechanical cohorts do not establish universal high- versus low-bar superiority, one stance, one depth, one torso angle, one muscle ranking, one safe load, or clinical clearance.'),
    environment_json=jsonb_build_object('surface','level_dry_non_slip','rack','rated_stable_and_anchored_per_manufacturer','hooks','matched_and_set_for_safe_unrack_and_rerack','safeties','matched_rated_and_set_below_valid_bottom_but_high_enough_to_receive_a_failed_bar','barAndPlates','rated_compatible_inspected_and_evenly_loaded','collars','used_per_facility_equipment_policy','walkout','minimal_clear_steps_inside_rack','clearance','bar_plates_athlete_spotters_and_safeties_clear','lighting','feet_bar_rack_safeties_and_observers_visible','emergencyPlan','declared_before_loading'),
    population_json=jsonb_build_object('defaultPopulation','healthy_participants_with_pain_free_loaded_squat_range_safe_bar_support_and_command_following','individualizationRequired',TRUE,
      'prerequisites',jsonb_build_array('can_use_assigned_bar_shelf_and_grip_without_symptom','can_unrack_walkout_squat_and_rerack_empty_bar_to_exact_commands','can_hold_declared_stance_depth_brace_and_pressure','understands_safeties_spotter_commands_and_failed_rep_plan','can_report_symptoms_fatigue_and_recovery'),
      'cautions',jsonb_build_array('current_foot_ankle_knee_hip_pelvis_spine_shoulder_elbow_or_wrist_symptoms','recent_injury_surgery_or_immobilization','uncontrolled_neurologic_cardiopulmonary_blood_pressure_or_pressure_symptoms','pregnancy_or_postpartum_status_requiring_individualized_loading','youth_or_other_population_requiring_qualified_supervision','inability_to_use_rack_safeties_or_escape_plan'),'notClinicalClearance',TRUE,'neverInferReadinessFromExerciseDifficulty',TRUE),
    athlete_support_json=jsonb_build_object('whatItIs','Place the bar on the assigned high- or low-bar shelf, brace before unracking, take the exact walkout and stance, squat to the declared depth on the assigned tempo, stand without changing the bar or foot position, reset, and rerack only on the coach command.',
      'before',jsonb_build_array('Confirm variant, bar shelf, grip, hook and safety height, load, walkout, stance and foot angle, depth, tempo, repetitions, sets, reserve, rest, spotter plan, stop and rerack commands.','Inspect the rack, bar, plates, collars under facility policy, floor, shoes, clearance, timer, observers, and emergency path.','Report pain, numbness, dizziness, unusual breathlessness, pressure symptoms, fear, or uncertainty before unracking.'),
      'during',jsonb_build_array('Keep the bar on its assigned shelf, feet planted, pressure controlled, and trunk and shank strategy repeatable.','Reach only the declared depth; do not chase range or load after control changes.','End before bar path, depth, tempo, brace, foot pressure, symmetry, or speed materially degrades.','Finish standing and stable, wait for the rack command, contact both hooks, and confirm the bar is secure before releasing.'),
      'expectedSensations',jsonb_build_array('lower_body_effort','trunk_and_upper_back_bracing','whole_foot_pressure','increasing_but_controlled_breathing'),
      'notExpected',jsonb_build_array('sharp_or_increasing_joint_or_spine_pain','numbness_tingling_or_weakness','dizziness_faintness_unusual_breathlessness_or_pressure_symptoms','bar_slip_or_uncontrolled_contact','panic_or_uncertain_rerack'),
      'selfChecks',jsonb_build_array('correct_bar_shelf_grip_and_load','hooks_and_safeties_set','walkout_and_stance_exact','feet_stay_planted','depth_tempo_and_bar_path_repeat','reserve_preserved','stable_two_hook_rerack'),
      'accessibility',jsonb_build_array('lighter_bar_or_load','fewer_repetitions','smaller_declared_range','more_rest_and_setup_time','visual_stance_depth_and_rack_marks','written_still_or_captioned_instruction','separately_reviewed_front_box_or_machine_squat_substitution'),
      'stopSignal','Stop the attempt according to the declared safety plan, use the safeties or spotters if needed, remain with the bar until it is secure, step clear only on command, and report what changed.'),
    coach_support_json=jsonb_build_object('setupChecklist',jsonb_build_array('verify_exact_variant_profile_bar_shelf_and_grip','inspect_rack_bar_plates_hooks_safeties_floor_clearance_and_timer','declare_load_walkout_stance_foot_angle_depth_tempo_repetitions_sets_reserve_rest_and_commands','assign_spotters_or_safety_only_plan_per_facility_policy','review_recent_lower_body_axial_sprint_jump_and_sport_load_plus_symptoms_and_recovery'),
      'observeFromSide',jsonb_build_array('bar_shelf_and_path','trunk_and_shank_strategy','hip_knee_ankle_sequence','depth_and_pelvic_control','tempo_speed_brace_and_rerack'),
      'observeFromFrontOrRear',jsonb_build_array('stance_and_foot_angle','whole_foot_pressure','knee_and_hip_path','bar_level_and_side_shift','walkout_and_two_hook_rerack'),
      'correctionOrder',jsonb_build_array('wrong_variant_load_or_rack_setup','symptom_or_emergency_stop','bar_shelf_grip_safety_or_escape_risk','walkout_stance_and_foot_pressure','depth_path_brace_and_tempo','repetition_reserve_and_fatigue','duration_recovery_and_persistence'),
      'countingRule','Count only repetitions that preserve the assigned bar shelf, stance, depth, path, tempo, brace, foot pressure, symmetry, completion, reserve, and safety plan. Record failed or stopped attempts and asymmetries separately.',
      'groupManagement',jsonb_build_array('one_active_lifter_per_rack','coach_controls_load_changes_and_rack_settings','no_person_crosses_bar_or_walkout_zone','spotters_use_predeclared_positions_and_commands','bar_is_secured_before_anyone_changes_plates_or_leaves'),
      'escalation','Quarantine selection when identity, bar position, grip, rack, safeties, load, stance, depth, symptoms, dose, recovery, supervision, or failed-rep plan is uncertain.'),
    support_operations_json=jsonb_build_object('selectionInputs',jsonb_build_array('definition_variant_profile_card_and_research_version','objective_and_phase','bar_type_position_grip_and_load','rack_hook_safety_spotter_and_escape_plan','walkout_stance_foot_angle_depth_tempo_and_brace','sets_repetitions_reserve_rest_and_duration','recent_lower_body_axial_running_sprint_jump_and_sport_load','symptoms_recovery_population_and_supervision'),
      'persistence',jsonb_build_array('workout_and_item_id','definition_variant_profile_card_and_research_version','bar_position_grip_load_and_rack_settings','walkout_stance_foot_angle_depth_tempo_and_brace','sets_valid_failed_and_stopped_repetitions','reserve_rest_faults_symptoms_duration_and_recovery','substitution_reason','rendered_athlete_and_coach_instruction_versions'),
      'memberSupport',jsonb_build_array('show_setup_unrack_walkout_descent_bottom_ascent_and_rerack','label_bar_shelf_grip_load_stance_depth_tempo_repetitions_rest_and_commands','define_valid_repetition_expected_sensations_and_stop','provide_captioned_and_nonvideo_equivalents'),
      'coachSupport',jsonb_build_array('show_side_and_front_or_rear_observation_points','surface_rack_load_depth_tempo_fault_symptom_and_recovery_log','surface_cumulative_lower_body_axial_and_sprint_jump_budgets','require_substitution_revalidation','retain_incident_and_escalation_logs'),
      'incidentPath',jsonb_build_array('call_stop_or_failed_rep_command','secure_bar_on_safeties_hooks_or_with_spotters','record_variant_load_rack_depth_dose_fault_symptom_and_context','follow_facility_emergency_or_clinical_referral_policy','quarantine_uncertain_card_source_or_media','do_not_diagnose_or_clear_in_product'),
      'changeImpact','Any bar, shelf, grip, rack, safety, walkout, stance, foot angle, depth, load, tempo, dose, fatigue, recovery, population, station, or media change invalidates cached selection, duration, logistics, rendering, and approval assumptions.'),
    provenance_json=coalesce(provenance_json,'{}'::JSONB)||jsonb_build_object('backSquatCompletionMigration',migration_key,'researchVersion',research_version,'canonicalAuthoredFromResearch',TRUE,'legacySourcesQuarantined',source_ids,'activeWorkingSpecifications',jsonb_build_array('high-bar-free-bar-parallel','low-bar-free-bar-parallel'),'primaryResearchSource','https://pubmed.ncbi.nlm.nih.gov/38900172/','researchSources',jsonb_build_array('https://pubmed.ncbi.nlm.nih.gov/38900172/','https://pubmed.ncbi.nlm.nih.gov/34541522/','https://pubmed.ncbi.nlm.nih.gov/38036316/','https://pmc.ncbi.nlm.nih.gov/articles/PMC4064719/','https://pubmed.ncbi.nlm.nih.gov/31230110/','https://www.nsca.com/contentassets/116c55d64e1343d2b264e05aaf158a91/basics_of_strength_and_conditioning_manual.pdf','https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/'),'identityDecision','bilateral_free_bar_posterior_shoulder_girdle_squat_with_bar_position_stance_depth_and_safety_as_explicit_dimensions','mediaState','five_current_oembed_healthy_candidates_unreviewed','oembedCheckedAt','2026-08-02','exerciseDifficultyModel','exercise_complexity_and_physical_difficulty_only','approvalsCreated',FALSE,'mediaApprovalCreated',FALSE,'graphApprovalCreated',FALSE,'calibrationApprovalCreated',FALSE,'cardApprovalCreated',FALSE,'publicationQuarantined',TRUE,'humanReviewRequired',TRUE),
    approved_video_url=NULL,reviewed_by=NULL,approved_by=NULL,last_reviewed_at=NULL,updated_at=now()
  WHERE id=canonical_id;

  INSERT INTO coaching.exercise_variant_v1(id,definition_id,variant_key,display_name,modifier_keys,difficulty_json,requirements_json,status,load_profile_json,fatigue_profile_json,programming_profile_json)
  SELECT v.id,canonical_id,v.variant_key,v.display_name,v.modifier_keys,
    jsonb_build_object('technicalComplexity',v.complexity,'absoluteLoadDemand',v.physical,'physicalDifficulty',v.physical,'baseOverallDifficulty',GREATEST(v.complexity,v.physical),'coordinationDemand',v.coordination,'supervisionDemand',v.supervision,'failureConsequence',v.failure,'impact',1,'workCapacityDemand',v.work_capacity,'provisional',TRUE,'difficultyModel','max_exercise_complexity_physical_difficulty','technicalMeaning','exercise_complexity','loadMeaning','physical_difficulty','athleteReadinessStoredHere',FALSE),
    jsonb_build_object('actionIdentity','bilateral_free_bar_back_squat','barType','straight_barbell','barPosition',v.bar_position,'barShelf',v.bar_shelf,'grip','closed_pronated_grip_width_individualized_and_recorded','rack','power_or_squat_rack_with_hooks_and_safeties','walkout','stand_bar_clear_then_two_or_three_controlled_steps_to_declared_stance','stance','individualized_recorded_and_repeated','footAngle','individualized_recorded_and_repeated','depthTarget','hip_crease_near_top_of_knee_parallel_target_or_shallower_if_individualized_and_recorded','tempo','controlled_descent_no_prescribed_pause_controlled_ascent','bouncePolicy','no_unplanned_bounce','laterality','bilateral','terminalAction','stand_stable_then_two_hook_rerack_on_command','selectable',TRUE,'identityQuarantine',FALSE,'workingSpecificationRequiresHumanContentReview',TRUE),
    'review',
    jsonb_build_object('gripDemand',v.grip,'externalLoadMethod','barbell_and_plates','externalLoadDescription','Known total bar and plate mass supported on the declared posterior shoulder-girdle shelf.','spinalLoading',v.spinal,'eccentricStress',v.eccentric,'landingContactsPerRep',0,'impactClass','no_flight_or_landing_impact','loadTracking',jsonb_build_array('bar_and_plate_mass','bar_position','grip','stance','depth','tempo','valid_failed_and_stopped_repetitions','reserve','symptoms'),'effectiveLoadDrivers',jsonb_build_array('external_mass','bar_position_and_grip','stance_and_foot_angle','depth_and_range','tempo_and_pause','repetitions_and_effort_reserve','anthropometry_and_strategy','recent_lower_body_axial_sprint_jump_and_sport_load')),
    jsonb_build_object('localMuscleFatigue',v.local_fatigue,'gripFatigue',v.grip,'technicalFatigueSensitivity',v.sensitivity,'neuralOutputDemand',v.neural,'impactAccumulation',1,'recoveryHours','24_to_96_context_dependent','primaryFatigueSites',jsonb_build_array('quadriceps_gluteals_and_adductors','trunk_and_spinal_support','upper_back_and_shoulder_girdle_bar_support','foot_ankle_and_calf_pressure_control'),'earlyFatigueSignals',jsonb_build_array('bar_speed_or_path_loss','depth_or_tempo_change','brace_or_trunk_strategy_change','foot_pressure_or_side_shift','bar_shelf_grip_or_elbow_change','walkout_or_rerack_uncertainty'),'downstreamConflicts',jsonb_build_array('priority_sprint_jump_cut_or_weightlifting_work','other_heavy_lower_body_or_axial_loading','high_volume_running_or_sport_contacts','symptomatic_lower_body_spine_or_shoulder_loading')),
    jsonb_build_object('primaryIntent','bilateral_lower_body_strength_and_capacity','selectionStatus','candidate_requires_human_review','appropriatePhases',jsonb_build_array('capacity'),'prerequisites',jsonb_build_array('pain_free_loaded_squat_setup_and_range','safe_bar_shelf_grip_walkout_and_rerack','rack_safeties_and_failed_rep_plan_verified','repeatable_stance_depth_tempo_brace_and_pressure','can_follow_commands_and_report_symptoms'),'completionCriteria',jsonb_build_array('all_valid_repetitions_match_exact_identity','bar_shelf_stance_depth_path_tempo_brace_and_pressure_thresholds_met','reserve_preserved','safe_rerack_and_exit','load_faults_symptoms_duration_and_recovery_recorded'),'avoidUse',jsonb_build_array('unknown_bar_position_rack_safety_load_stance_depth_tempo_or_escape_plan','pain_guarding_neurologic_cardiopulmonary_or_pressure_symptom','unsafe_equipment_clearance_spotting_or_supervision','cannot_control_walkout_depth_brace_path_or_rerack','fatigue_or_recovery_conflicts_with_priority_work'),'cumulativeBudget',jsonb_build_object('loadedSquatValidRepetitions',1,'axialLoadExposure',v.axial_budget,'kneeHipExtensorLoad',v.lower_budget,'localLowerBodyFatigue',v.local_fatigue,'athleteLandingImpactContacts',0),'weeklyExposureGuidance','Combine all loaded squat, hinge, carry, sprint, jump, running, lifting, and sport exposures. Progress one of load, repetitions, sets, range, tempo, pause, or frequency after stable quality and recovery.','sequencing','Place after freshness-sensitive sprint, jump, cut, throw, or weightlifting work unless the squat is the session priority. Use full rest; do not turn a strength profile into conditioning.','pairingCompatibility',jsonb_build_array('noncompeting_low_risk_upper_body_or_breathing_task_during_full_rest'),'interferenceRules',jsonb_build_array('do_not_pre_fatigue_lower_body_or_trunk_before_priority_output','do_not_chase_load_after_bar_path_depth_brace_or_speed_changes','recompute_identity_load_range_fatigue_recovery_duration_equipment_station_and_rendering_after_substitution'),'uncertaintyPolicy',jsonb_build_object('unknownIdentityLoadSymptomsSafetyOrRecovery','fail_closed_and_request_coach_review','neverInferMissingSourceMechanics',TRUE,'neverAutoApproveMediaGraphCalibrationOrPublication',TRUE))
  FROM (VALUES
    (high_bar_variant,'high-bar-free-bar-parallel','Back Squat — High-Bar Free Bar, Parallel Target',ARRAY['high_bar','free_bar','bilateral','parallel_target','full_cycle']::TEXT[],'high_bar','upper_trapezius_shelf',64,70,64,72,72,60,70,68,64,70,58,70,0.8,72),
    (low_bar_variant,'low-bar-free-bar-parallel','Back Squat — Low-Bar Free Bar, Parallel Target',ARRAY['low_bar','free_bar','bilateral','parallel_target','full_cycle']::TEXT[],'low_bar','posterior_deltoid_shelf_below_trapezial_ridge',68,74,68,76,76,64,74,72,68,74,62,74,0.9,76)
  ) v(id,variant_key,display_name,modifier_keys,bar_position,bar_shelf,complexity,physical,coordination,supervision,failure,work_capacity,local_fatigue,sensitivity,neural,spinal,eccentric,grip,axial_budget,lower_budget)
  ON CONFLICT(id) DO UPDATE SET definition_id=EXCLUDED.definition_id,variant_key=EXCLUDED.variant_key,display_name=EXCLUDED.display_name,modifier_keys=EXCLUDED.modifier_keys,difficulty_json=EXCLUDED.difficulty_json,requirements_json=EXCLUDED.requirements_json,status='review',load_profile_json=EXCLUDED.load_profile_json,fatigue_profile_json=EXCLUDED.fatigue_profile_json,programming_profile_json=EXCLUDED.programming_profile_json,updated_at=now();

  INSERT INTO coaching.exercise_delivery_profile_v1(variant_id,profile_key,phase_key,role,purpose,phase_suitability,methodology_alignment,objective_relevance_json,dosage_json,quality_gate,stop_rules,coach_instructions,athlete_instructions,expected_adaptation,equipment_required,logistics_json,substitution_ids,status,time_model_json,dose_scaling_json,measurement_json,support_prompts_json)
  SELECT p.variant_id,p.profile_key,'capacity',p.role,p.purpose,p.suitability,92,
    jsonb_build_object('bilateralStrength',5,'lowerBodyCapacity',p.capacity,'axialLoadTolerance',p.axial,'jumpSupport',p.jump_support,'athleteLandingImpact',0),
    jsonb_build_object('doseType','valid_repetitions','sets',p.sets,'repetitionsPerSet',p.reps,'laterality','bilateral','depthTarget','parallel_target_or_individualized_shallower_range_recorded','tempo','controlled_descent_no_pause_controlled_ascent','effortReserve',p.reserve,'restSeconds',p.rest,'qualityThreshold','end_before_bar_path_depth_tempo_brace_foot_pressure_symmetry_or_rerack_materially_changes'),
    'Every counted repetition uses the assigned bar shelf, grip, load, walkout, stance, foot angle, depth, tempo, brace, foot pressure, bar path, full standing finish, reserve, and safe two-hook rerack without a stop-rule failure.',
    ARRAY['pain_or_neurologic_symptom','dizziness_faintness_unusual_breathlessness_or_pressure_symptom','wrong_variant_bar_shelf_grip_load_rack_safety_stance_depth_or_tempo','rack_hook_safety_bar_plate_collar_floor_clearance_or_spotter_plan_is_unsafe','bar_moves_on_back_or_grip_cannot_be_maintained','foot_loses_surface_or_pressure_shifts_uncontrollably','depth_path_brace_trunk_or_knee_strategy_materially_changes','tempo_repetition_count_or_command_breaks','bar_speed_loss_exceeds_profile_or_missed_rep_risk_rises','walkout_rerack_or_two_hook_contact_is_uncertain','effort_reserve_or_duration_ceiling_exceeded','recovery_or_priority_output_budget_is_not_acceptable'],
    'Verify exact high- or low-bar profile, shelf, grip, rack hooks and safeties, bar and load, walkout, stance, foot angle, depth, tempo, repetitions, sets, reserve, rest, spotter or safety-only plan, stop and rerack commands, and recent loading. Observe from side and front or rear; count only exact valid repetitions and secure the bar before recording.',
    'Set the assigned bar shelf and grip, brace, stand clear, take the exact walkout, and plant the recorded stance. Squat only to the assigned depth on tempo, stand with the bar and feet controlled, and reset. Stop before the rep changes. Rerack on command, touch both hooks, and release only after the bar is secure.',
    p.adaptation,ARRAY['barbell','plates','squat_rack','timer']::TEXT[],
    jsonb_build_object('athletesPerStation',1,'setupSeconds',120,'transitionSeconds',45,'equipmentCheck','rated_rack_bar_plates_hooks_safeties_floor_clearance_timer_and_declared_spotter_or_safety_plan','station','dedicated_barbell_squat_rack','loadChangeRule','coach_controls_both_sides_and_confirms_equal_loading_and_security','substitutionRevalidation',jsonb_build_array('identity','bar_position','grip','rack','safeties','walkout','stance','depth','load','tempo','fatigue','recovery','duration','population','rendering')),
    CASE WHEN p.variant_id=high_bar_variant THEN ARRAY[low_bar_variant,front_squat_variant,box_squat_variant]::UUID[] ELSE ARRAY[high_bar_variant,front_squat_variant,pin_squat_variant]::UUID[] END,'review',
    jsonb_build_object('setupSeconds',120,'secondsPerRep',p.seconds_per_rep,'transitionSeconds',45,'durationFormula','setup + sets * (repetitions * seconds_per_rep + rest) + transition','durationCeilingSeconds',p.ceiling),
    jsonb_build_object('reduce',jsonb_build_array('reduce_load','reduce_repetitions','reduce_sets','reduce_declared_range','increase_rest','use_separately_reviewed_front_box_or_machine_squat'),'increase',jsonb_build_array('increase_load','increase_repetitions_within_profile','increase_sets_within_budget','increase_owned_range','use_separately_reviewed_pause_or_tempo_variant'),'revalidateAfterChange',TRUE),
    jsonb_build_object('record',jsonb_build_array('definition_id','variant_id','profile_key','bar_position_grip_and_load','rack_hook_safety_and_spotter_plan','walkout_stance_foot_angle_depth_and_tempo','sets_valid_failed_and_stopped_repetitions','reserve_rest_faults_symptoms_duration_and_recovery','substitution'),'validity','all exact identity, rack, safety, range, path, tempo, brace, pressure, reserve, duration, and stop gates pass'),
    jsonb_build_object('before','Which variant, shelf, grip, load, hooks, safeties, walkout, stance, depth, tempo, dose, reserve, rest, and commands are assigned?','during','Are bar shelf and path, feet, pressure, depth, tempo, brace, symmetry, speed, reserve, and safety still valid?','after','Secure the bar, then store valid, failed, and stopped repetitions, load, faults, symptoms, duration, recovery, and substitution.')
  FROM (VALUES
    (high_bar_variant,'strength','primary','Build high-bar bilateral squat strength through a declared range with repeatable rack, walkout, stance, depth, path, brace, and rerack.',92,5,4,2,3,5,'2_to_3_clean_repetitions_in_reserve',180,8,'Improved high-bar bilateral squat force capacity and repeatable loaded positions.',900),
    (high_bar_variant,'volume','secondary','Build high-bar squat volume while preserving exact depth, tempo, path, reserve, safety, and recovery.',88,4,4,1,3,8,'2_to_4_clean_repetitions_in_reserve',150,8,'Improved high-bar squat work capacity and repeatable submaximal range.',1050),
    (low_bar_variant,'strength','primary','Build low-bar bilateral squat strength through a declared range with repeatable shelf, walkout, stance, depth, path, brace, and rerack.',92,5,5,2,3,5,'2_to_3_clean_repetitions_in_reserve',180,8,'Improved low-bar bilateral squat force capacity and repeatable loaded positions.',900),
    (low_bar_variant,'volume','secondary','Build low-bar squat volume while preserving exact shelf, depth, tempo, path, reserve, safety, and recovery.',86,4,5,1,3,8,'2_to_4_clean_repetitions_in_reserve',150,8,'Improved low-bar squat work capacity and repeatable submaximal range.',1050)
  ) p(variant_id,profile_key,role,purpose,suitability,capacity,axial,jump_support,sets,reps,reserve,rest,seconds_per_rep,adaptation,ceiling)
  ON CONFLICT(variant_id,profile_key) DO UPDATE SET phase_key=EXCLUDED.phase_key,role=EXCLUDED.role,purpose=EXCLUDED.purpose,phase_suitability=EXCLUDED.phase_suitability,methodology_alignment=EXCLUDED.methodology_alignment,objective_relevance_json=EXCLUDED.objective_relevance_json,dosage_json=EXCLUDED.dosage_json,quality_gate=EXCLUDED.quality_gate,stop_rules=EXCLUDED.stop_rules,coach_instructions=EXCLUDED.coach_instructions,athlete_instructions=EXCLUDED.athlete_instructions,expected_adaptation=EXCLUDED.expected_adaptation,equipment_required=EXCLUDED.equipment_required,logistics_json=EXCLUDED.logistics_json,substitution_ids=EXCLUDED.substitution_ids,status='review',time_model_json=EXCLUDED.time_model_json,dose_scaling_json=EXCLUDED.dose_scaling_json,measurement_json=EXCLUDED.measurement_json,support_prompts_json=EXCLUDED.support_prompts_json,updated_at=now();

  INSERT INTO coaching.exercise_section_evidence_v1(definition_id,reviewed_card_version,section_key,source_url,source_title,source_publisher,source_kind,claims_json,evidence_quality,review_status,reviewer_user_id,reviewed_at)
  SELECT canonical_id,2,item->>'sectionKey',item->>'sourceUrl',item->>'sourceTitle',item->>'sourcePublisher',item->>'sourceKind',item->'claims'||jsonb_build_array(jsonb_build_object('migration',migration_key,'researchVersion',research_version,'humanReviewRequired',TRUE,'approvalsCreated',FALSE)),(item->>'evidenceQuality')::SMALLINT,'candidate',NULL,NULL FROM jsonb_array_elements(evidence_payload) item
  ON CONFLICT(definition_id,reviewed_card_version,section_key,source_url) DO UPDATE SET source_title=EXCLUDED.source_title,source_publisher=EXCLUDED.source_publisher,source_kind=EXCLUDED.source_kind,claims_json=EXCLUDED.claims_json,evidence_quality=EXCLUDED.evidence_quality,review_status='candidate',reviewer_user_id=NULL,reviewed_at=NULL,updated_at=now();

  INSERT INTO coaching.exercise_media_candidate_v1(definition_id,variant_id,reviewed_card_version,url,embed_url,video_id,title,channel_name,language_code,captions_available,embedding_allowed,exact_variant_match,demonstration_quality_score,link_status,review_status,discovery_method,source_query,reviewer_user_id,reviewed_at,next_review_at,notes)
  SELECT canonical_id,CASE item->>'variant' WHEN 'high' THEN high_bar_variant WHEN 'low' THEN low_bar_variant ELSE NULL END,2,'https://www.youtube.com/watch?v='||(item->>'videoId'),'https://www.youtube-nocookie.com/embed/'||(item->>'videoId'),item->>'videoId',item->>'title',item->>'channel','en',NULL,TRUE,NULL,NULL,'healthy','candidate','manual_research',item->>'query',NULL,NULL,'2026-11-02T00:00:00.000Z'::TIMESTAMPTZ,'YouTube oEmbed link, title, channel, and iframe metadata returned HTTP 200 on 2026-08-02. Full playback and exact bar shelf, grip, rack, safety, walkout, stance, depth, tempo, load, rerack, cue safety, conflicts, captions, accessibility, quality, reviewer, and approval remain unresolved.' FROM jsonb_array_elements(media_payload) item
  ON CONFLICT(definition_id,reviewed_card_version,video_id) DO UPDATE SET variant_id=EXCLUDED.variant_id,url=EXCLUDED.url,embed_url=EXCLUDED.embed_url,title=EXCLUDED.title,channel_name=EXCLUDED.channel_name,language_code='en',captions_available=NULL,embedding_allowed=TRUE,exact_variant_match=NULL,demonstration_quality_score=NULL,link_status='healthy',review_status='candidate',discovery_method='manual_research',source_query=EXCLUDED.source_query,reviewer_user_id=NULL,reviewed_at=NULL,next_review_at=EXCLUDED.next_review_at,notes=EXCLUDED.notes,updated_at=now();

  INSERT INTO coaching.exercise_alternate_assessment_v1(definition_id,reviewed_card_version,alternate_name,classification,rationale,distinguishing_dimensions,proposed_card_json,review_status,reviewer_user_id,reviewed_at)
  SELECT canonical_id,2,item->>'name',item->>'class',item->>'why',item->'dimensions',NULL,'candidate',NULL,NULL FROM jsonb_array_elements(alternate_payload) item
  ON CONFLICT(definition_id,reviewed_card_version,alternate_name) DO UPDATE SET classification=EXCLUDED.classification,rationale=EXCLUDED.rationale,distinguishing_dimensions=EXCLUDED.distinguishing_dimensions,proposed_card_json=NULL,review_status='candidate',reviewer_user_id=NULL,reviewed_at=NULL,updated_at=now();

  INSERT INTO coaching.exercise_relationship_v1(from_variant_id,to_variant_id,relationship,similarity_score,dimensions,reason,conditions_json,review_status,created_by,reviewed_by,reviewed_at) VALUES
    (high_bar_variant,low_bar_variant,'lateral_substitution',92,ARRAY['leverage','complexity'],'Both are bilateral free-bar back squats; bar shelf, grip, torso strategy, comfort, load, and rack handling must be revalidated.',jsonb_build_object('revalidate',jsonb_build_array('bar_position','grip','stance','depth','load','safety','dose','fatigue','duration','rendering')),'review',NULL,NULL,NULL),
    (low_bar_variant,high_bar_variant,'lateral_substitution',92,ARRAY['leverage','complexity'],'High-bar preserves the bilateral free-bar squat but changes shelf, grip, torso strategy, comfort, load, and rack handling.',jsonb_build_object('revalidate',jsonb_build_array('bar_position','grip','stance','depth','load','safety','dose','fatigue','duration','rendering')),'review',NULL,NULL,NULL),
    (high_bar_variant,front_squat_variant,'lateral_substitution',78,ARRAY['leverage','stability','complexity'],'Front squat changes the bar to an anterior shoulder interface, grip, torso strategy, failure response, and rerack.',jsonb_build_object('revalidate',jsonb_build_array('identity','bar_interface','grip','load','depth','safety','fatigue','duration','rendering')),'review',NULL,NULL,NULL),
    (front_squat_variant,high_bar_variant,'lateral_substitution',78,ARRAY['leverage','stability','complexity'],'High-bar changes the bar to a posterior shelf and requires a different grip, walkout, failure response, and rerack.',jsonb_build_object('revalidate',jsonb_build_array('identity','bar_interface','grip','load','depth','safety','fatigue','duration','rendering')),'review',NULL,NULL,NULL),
    (high_bar_variant,box_squat_variant,'lateral_substitution',72,ARRAY['range','complexity'],'Box squat adds box height and contact, touch-or-sit behavior, pressure transfer, reversal, and box safety.',jsonb_build_object('revalidate',jsonb_build_array('identity','box','range','contact','load','safety','dose','rendering')),'review',NULL,NULL,NULL),
    (box_squat_variant,high_bar_variant,'lateral_substitution',72,ARRAY['range','complexity'],'High-bar free squat removes box contact and requires an unsupported declared depth and reversal.',jsonb_build_object('revalidate',jsonb_build_array('identity','range','reversal','load','safety','dose','rendering')),'review',NULL,NULL,NULL),
    (high_bar_variant,tempo_five_variant,'lateral_substitution',84,ARRAY['speed','fatigue','complexity'],'The exact five-second-lower variant changes eccentric duration, fatigue, dose, duration, and recovery.',jsonb_build_object('revalidate',jsonb_build_array('tempo','load','dose','fatigue','recovery','duration','rendering')),'review',NULL,NULL,NULL),
    (low_bar_variant,pin_squat_variant,'lateral_substitution',70,ARRAY['range','stability','complexity'],'Pin squat changes start or stop contact, pin height, contraction sequence, bar contact, and escape plan.',jsonb_build_object('revalidate',jsonb_build_array('identity','pins','range','contraction_sequence','load','safety','dose','rendering')),'review',NULL,NULL,NULL)
  ON CONFLICT(from_variant_id,to_variant_id,relationship) DO UPDATE SET similarity_score=EXCLUDED.similarity_score,dimensions=EXCLUDED.dimensions,reason=EXCLUDED.reason,conditions_json=EXCLUDED.conditions_json,review_status='review',created_by=NULL,reviewed_by=NULL,reviewed_at=NULL,updated_at=now()
  WHERE coaching.exercise_relationship_v1.reviewed_by IS NULL AND coaching.exercise_relationship_v1.review_status<>'approved';

  INSERT INTO coaching.exercise_identity_resolution_v1(facility_id,survivor_definition_id,resolved_definition_id,decision,rationale,evidence_json,resolution_source,reviewed_by)
  SELECT 1,canonical_id,definition_id,'duplicate_consolidated',CASE definition_id
    WHEN '57bc5cdb-b4a7-4840-ada0-920b335898b7'::UUID THEN 'High-Bar Back Squat is an exact bar-position variant within Back Squat. Source 367 remains quarantined because its grip, stance, depth, walkout, tempo, safety, and rerack contract is incomplete.'
    WHEN '80d7a8c7-58a9-462c-92c5-bb01dc98222c'::UUID THEN 'Low-Bar Back Squat is an exact bar-position variant within Back Squat. Source 368 remains quarantined because its grip, stance, depth, walkout, tempo, safety, and rerack contract is incomplete.'
    WHEN '5e699119-b268-451c-9153-299f8830f151'::UUID THEN 'Pause Back Squat belongs to the family when exact bar position, depth, pause duration, rebound policy, load, and safety are declared; source 370 omits them and remains nonselectable.'
    ELSE 'Tempo Back Squat belongs to the family when exact bar position and phase durations are declared; source 371 supplies neither and remains nonselectable.' END,
    jsonb_build_object('migration',migration_key,'identityBoundary','bilateral_free_bar_posterior_shoulder_girdle_squat_family_with_exact_bar_position_stance_depth_tempo_and_safety_dimensions','sourceVariantSelectable',FALSE,'humanReviewRequired',TRUE,'approvalsCreated',FALSE),'deterministic_identity_equivalence',NULL
  FROM unnest(archived_definition_ids) definition_id
  ON CONFLICT(survivor_definition_id,resolved_definition_id) DO UPDATE SET decision=EXCLUDED.decision,rationale=EXCLUDED.rationale,evidence_json=EXCLUDED.evidence_json,resolution_source=EXCLUDED.resolution_source,reviewed_by=NULL,resolved_at=now()
  WHERE coaching.exercise_identity_resolution_v1.reviewed_by IS NULL AND coaching.exercise_identity_resolution_v1.resolution_source<>'human_review';

  INSERT INTO coaching.exercise_identity_resolution_v1(facility_id,survivor_definition_id,resolved_definition_id,decision,rationale,evidence_json,resolution_source,reviewed_by)
  VALUES
    (1,canonical_id,'60f6a322-403a-411f-b300-0342bfcd6c6f'::UUID,'distinct_exercises','Back Squat has no support contact at the bottom. Box Squat requires a declared box height and intentional contact plus touch-or-sit, pressure-transfer, reversal, and box-safety rules.',jsonb_build_object('migration',migration_key,'identityBoundary','unsupported_free_bar_squat_vs_declared_box_contact_squat','humanReviewRequired',TRUE,'approvalsCreated',FALSE),'deterministic_identity_equivalence',NULL),
    (1,canonical_id,'5ffbb327-0143-4d44-9230-89b0e0bc0577'::UUID,'distinct_exercises','Back Squat uses a bilateral parallel stance and posterior free-bar load. Split Squat uses a stationary split stance with unilateral emphasis, different base, laterality, balance, and side-dose rules.',jsonb_build_object('migration',migration_key,'identityBoundary','bilateral_parallel_stance_back_squat_vs_stationary_split_stance_squat','humanReviewRequired',TRUE,'approvalsCreated',FALSE),'deterministic_identity_equivalence',NULL),
    (1,canonical_id,'74b636ed-eb74-4dcb-af92-dc018ff72faa'::UUID,'distinct_exercises','Back Squat supports the bar on a posterior shoulder-girdle shelf. Front Squat supports it on the anterior shoulders, changing interface, grip, torso strategy, failure response, and rerack.',jsonb_build_object('migration',migration_key,'identityBoundary','posterior_bar_shelf_back_squat_vs_anterior_shoulder_front_squat','humanReviewRequired',TRUE,'approvalsCreated',FALSE),'deterministic_identity_equivalence',NULL)
  ON CONFLICT(survivor_definition_id,resolved_definition_id) DO UPDATE SET decision='distinct_exercises',rationale=EXCLUDED.rationale,evidence_json=EXCLUDED.evidence_json,resolution_source=EXCLUDED.resolution_source,reviewed_by=NULL,resolved_at=now()
  WHERE coaching.exercise_identity_resolution_v1.reviewed_by IS NULL AND coaching.exercise_identity_resolution_v1.resolution_source<>'human_review';

  INSERT INTO coaching.exercise_score_calibration_v1(facility_id,variant_id,dimension,proposed_score,anchor_tier,rationale,status,version,created_by,reviewed_by,review_notes,reviewed_at)
  SELECT 1,v.id,d.key,CASE d.key WHEN 'technicalComplexity' THEN v.complexity ELSE v.physical END,80,
    CASE d.key WHEN 'technicalComplexity' THEN 'Review-only exercise-complexity anchor for exact bar shelf, grip, rack, safeties, walkout, stance, foot angle, depth, tempo, brace, path, commands, failed-rep plan, and rerack.' ELSE 'Review-only physical-difficulty anchor for external mass, range, repetitions, effort reserve, axial and lower-body load, fatigue, recent training overlap, symptoms, and recovery.' END||' No athlete proficiency classification is represented. Variant: '||v.variant_key||'.','review',1,NULL,NULL,NULL,NULL
  FROM (VALUES(high_bar_variant,'high-bar-free-bar-parallel',64,72),(low_bar_variant,'low-bar-free-bar-parallel',68,76)) v(id,variant_key,complexity,physical)
  CROSS JOIN (VALUES('technicalComplexity'),('absoluteLoadDemand')) d(key)
  ON CONFLICT(facility_id,variant_id,dimension,version) DO UPDATE SET proposed_score=EXCLUDED.proposed_score,anchor_tier=EXCLUDED.anchor_tier,rationale=EXCLUDED.rationale,status='review',created_by=NULL,reviewed_by=NULL,review_notes=NULL,reviewed_at=NULL,updated_at=now();

  UPDATE coaching.exercise SET skill_level=NULL,updated_at=now() WHERE id=ANY(source_ids);
  UPDATE coaching.exercise_safety_profile SET minimum_skill_level=NULL WHERE exercise_id=ANY(source_ids);

  INSERT INTO coaching.exercise_card_test_packet_v1(definition_id,facility_id,card_version,schema_version,audit_version,status,checks_json,blocking_issues_json,human_review_required,checked_at)
  VALUES(canonical_id,1,2,'1.0.0',migration_key,'quarantined',jsonb_build_object(
    'identity',jsonb_build_object('passed',TRUE,'legacySources',5,'activeWorkingSpecifications',2,'sourceDerivedSelectableVariants',0,'identityQuarantinedSources',source_ids),
    'taxonomy',jsonb_build_object('passed',TRUE,'controlledTerms',TRUE,'movementPatterns',jsonb_build_array('squat','brace')),
    'anatomy',jsonb_build_object('passed',TRUE,'musclesTissuesJointsActionsPlanesLaterality',TRUE,'universalMuscleRankingClaim',FALSE),
    'difficulty',jsonb_build_object('passed',TRUE,'model','max_exercise_complexity_physical_difficulty','athleteProficiency',NULL,'independentCalibrationRequired',TRUE),
    'loadFatigueRecovery',jsonb_build_object('passed',TRUE,'barMassRangeTempoReserveAxialLowerBodyAndCumulativeBudgets',TRUE,'landingImpactContacts',0),
    'constraints',jsonb_build_object('passed',TRUE,'rackHooksSafetiesBarPlatesWalkoutClearanceSpotterEscapePopulation',TRUE),
    'delivery',jsonb_build_object('passed',TRUE,'profiles',4,'durationScalingDoseRestStationAndRerackLogistics',TRUE),
    'instructions',jsonb_build_object('passed',TRUE,'athleteCoachSupport',TRUE,'setupUnrackWalkoutSquatFinishRerackAndStopRules',TRUE),
    'research',jsonb_build_object('passed',TRUE,'sections',16,'registryVersion',research_version,'limitationsExplicit',TRUE),
    'media',jsonb_build_object('passed',FALSE,'candidateCount',5,'oEmbedMetadataHealthy',TRUE,'playbackReviewed',FALSE,'exactMatchReviewed',FALSE,'captionsReviewed',FALSE,'accessibilityReviewed',FALSE,'qualityReviewed',FALSE,'approvalCreated',FALSE),
    'relationships',jsonb_build_object('passed',FALSE,'reviewOnly',8,'approved',0),'calibration',jsonb_build_object('passed',FALSE,'reviewOnly',4,'approved',0),
    'alternates',jsonb_build_object('passed',TRUE,'assessments',24,'sourceIdentityQuarantines',5),
    'generationSupport',jsonb_build_object('passed',TRUE,'selectionConstraints',TRUE,'cumulativeLowerBodyAxialRunningSprintJumpBudget',TRUE,'duration',TRUE,'equipmentStationAndSafety',TRUE,'substitutionRevalidation',TRUE,'renderingAndPersistence',TRUE),
    'publication',jsonb_build_object('passed',FALSE,'reviewer',NULL,'approver',NULL)),
    jsonb_build_array(
      jsonb_build_object('code','CARD-MEDIA-01','message','A qualified human must watch every candidate in full and verify exact bar shelf, grip, rack, safeties, walkout, stance, depth, tempo, load, rerack, captions, safety, accessibility, conflicts, and quality.'),
      jsonb_build_object('code','CARD-GRAPH-03','message','A qualified coach must approve or reject every progression, regression, substitution, and equipment proposal.'),
      jsonb_build_object('code','CARD-CALIBRATION-01','message','An independent qualified reviewer must calibrate exercise complexity and physical difficulty; these scores are not athlete proficiency.'),
      jsonb_build_object('code','CARD-PUBLISH-01','message','A qualified reviewer and separate approver must complete content review before publication. All five legacy sources require exact original specifications before any source-derived variant is restored.')),TRUE,now())
  ON CONFLICT(definition_id) DO UPDATE SET facility_id=EXCLUDED.facility_id,card_version=EXCLUDED.card_version,schema_version=EXCLUDED.schema_version,audit_version=EXCLUDED.audit_version,status='quarantined',checks_json=EXCLUDED.checks_json,blocking_issues_json=EXCLUDED.blocking_issues_json,human_review_required=TRUE,checked_at=now();

  IF (SELECT count(*) FROM coaching.exercise_definition_source_v1 WHERE definition_id=canonical_id AND legacy_exercise_id=ANY(source_ids) AND provenance_json->>'sourceDisposition'='identity_quarantine')<>5
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id=ANY(source_variant_ids) AND definition_id=canonical_id AND status='archived' AND requirements_json->>'representation'='identity_quarantine')<>5
    OR (SELECT count(*) FROM coaching.exercise_variant_v1 WHERE id=ANY(active_variant_ids) AND definition_id=canonical_id AND status='review' AND requirements_json->>'selectable'='true' AND difficulty_json->>'technicalMeaning'='exercise_complexity' AND difficulty_json->>'loadMeaning'='physical_difficulty' AND (difficulty_json->>'baseOverallDifficulty')::INTEGER=GREATEST((difficulty_json->>'technicalComplexity')::INTEGER,(difficulty_json->>'physicalDifficulty')::INTEGER) AND load_profile_json<>'{}'::JSONB AND fatigue_profile_json<>'{}'::JSONB AND programming_profile_json<>'{}'::JSONB)<>2 THEN
    RAISE EXCEPTION '% found invalid source quarantine or working specifications',migration_key;
  END IF;
  IF (SELECT count(*) FROM coaching.exercise_delivery_profile_v1 WHERE variant_id=ANY(active_variant_ids) AND status='review' AND coalesce(dosage_json->>'repetitionsPerSet','')<>'' AND cardinality(equipment_required)>=4 AND coalesce(time_model_json->>'durationFormula','')<>'' AND length(coach_instructions)>=100 AND length(athlete_instructions)>=100 AND cardinality(stop_rules)>=10)<>4
    OR (SELECT count(DISTINCT section_key) FROM coaching.exercise_section_evidence_v1 WHERE definition_id=canonical_id AND reviewed_card_version=2 AND review_status='candidate' AND reviewer_user_id IS NULL)<>16
    OR (SELECT count(*) FROM coaching.exercise_media_candidate_v1 WHERE definition_id=canonical_id AND reviewed_card_version=2 AND video_id=ANY(current_video_ids) AND link_status='healthy' AND review_status='candidate' AND embedding_allowed AND captions_available IS NULL AND exact_variant_match IS NULL AND demonstration_quality_score IS NULL AND reviewer_user_id IS NULL AND reviewed_at IS NULL)<>5
    OR (SELECT count(*) FROM coaching.exercise_alternate_assessment_v1 WHERE definition_id=canonical_id AND reviewed_card_version=2 AND review_status='candidate' AND reviewer_user_id IS NULL)<>24 THEN
    RAISE EXCEPTION '% found incomplete profiles, evidence, media, or alternates',migration_key;
  END IF;
  IF (SELECT count(*) FROM coaching.exercise_relationship_v1 WHERE (from_variant_id=ANY(active_variant_ids) OR to_variant_id=ANY(active_variant_ids)) AND review_status='review' AND reviewed_by IS NULL)<>8
    OR (SELECT count(*) FROM coaching.exercise_score_calibration_v1 WHERE variant_id=ANY(active_variant_ids) AND status='review' AND version=1 AND reviewed_by IS NULL)<>4
    OR (SELECT count(*) FROM coaching.exercise_identity_resolution_v1 WHERE survivor_definition_id=canonical_id AND resolved_definition_id=ANY(archived_definition_ids) AND reviewed_by IS NULL)<>4
    OR (SELECT count(*) FROM coaching.exercise_identity_resolution_v1 WHERE survivor_definition_id=canonical_id AND resolved_definition_id IN ('60f6a322-403a-411f-b300-0342bfcd6c6f'::UUID,'5ffbb327-0143-4d44-9230-89b0e0bc0577'::UUID,'74b636ed-eb74-4dcb-af92-dc018ff72faa'::UUID) AND decision='distinct_exercises' AND reviewed_by IS NULL)<>3 THEN
    RAISE EXCEPTION '% found incomplete graph, calibration, or identity resolution',migration_key;
  END IF;
  IF EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 d CROSS JOIN LATERAL unnest(d.movement_patterns) key WHERE d.id=canonical_id AND NOT EXISTS(SELECT 1 FROM coaching.movement_pattern a WHERE a.key=key))
    OR EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 d CROSS JOIN LATERAL unnest(d.body_regions) key WHERE d.id=canonical_id AND NOT EXISTS(SELECT 1 FROM coaching.body_region a WHERE a.key=key))
    OR EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 d CROSS JOIN LATERAL unnest(d.required_equipment||d.optional_equipment) key WHERE d.id=canonical_id AND NOT EXISTS(SELECT 1 FROM coaching.equipment a WHERE a.key=key))
    OR EXISTS(SELECT 1 FROM coaching.exercise_relationship_v1 r WHERE (r.from_variant_id=ANY(active_variant_ids) OR r.to_variant_id=ANY(active_variant_ids)) AND EXISTS(SELECT 1 FROM unnest(r.dimensions) dimension WHERE dimension<>ALL(ARRAY['load','leverage','range','speed','stability','complexity','impact','decision_demand','fatigue']))) THEN
    RAISE EXCEPTION '% created uncontrolled taxonomy or graph dimensions',migration_key;
  END IF;
  IF EXISTS(SELECT 1 FROM coaching.exercise WHERE id=ANY(source_ids) AND skill_level IS NOT NULL)
    OR EXISTS(SELECT 1 FROM coaching.exercise_safety_profile WHERE exercise_id=ANY(source_ids) AND minimum_skill_level IS NOT NULL)
    OR EXISTS(SELECT 1 FROM coaching.exercise_definition_v1 WHERE id=canonical_id AND (reviewed_by IS NOT NULL OR approved_by IS NOT NULL OR last_reviewed_at IS NOT NULL OR approved_video_url IS NOT NULL))
    OR EXISTS(SELECT 1 FROM coaching.exercise_media_candidate_v1 WHERE definition_id=canonical_id AND reviewed_card_version=2 AND (review_status IN ('approved') OR reviewer_user_id IS NOT NULL OR reviewed_at IS NOT NULL OR captions_available IS NOT NULL OR exact_variant_match IS NOT NULL OR demonstration_quality_score IS NOT NULL))
    OR EXISTS(SELECT 1 FROM coaching.exercise_card_test_packet_v1 WHERE definition_id=canonical_id AND (status<>'quarantined' OR human_review_required<>TRUE OR jsonb_array_length(blocking_issues_json)<>4)) THEN
    RAISE EXCEPTION '% fabricated proficiency, approval, or publication state',migration_key;
  END IF;
END;
$$;
